async ({ http: { request } }) => {
  const out: Record<string, string> = {};
  for (const t of ["read", "bash", "edit", "write"]) {
    const r = await request(`https://unpkg.com/@earendil-works/pi-coding-agent@1.5.2/dist/core/tools/${t}.js`, { maxBytes: 200000 });
    const lines = r.body.split("\n");
    const idx = lines.flatMap((l, i) => /promptSnippet|promptGuidelines/.test(l) ? [i] : []);
    out[t] = `${r.status}\n` + idx.map(i => lines.slice(i, i + 6).join("\n")).join("\n...\n");
  }
  return out;
}
